#!/bin/bash
set -e
TMPDIR="$(mktemp -d)"
echo "=== FIX Roles v3: 'is None' en vez de 'not collection' ==="
echo "" | base64 -d | tar xzf - -C "$TMPDIR"
cp "$TMPDIR/multitenancy_service.py" /opt/siempria-monitor/backend/services/multitenancy_service.py
cp "$TMPDIR/devices.py" /opt/siempria-monitor/backend/routes/devices.py
cp "$TMPDIR/dahua.py" /opt/siempria-monitor/backend/routes/dahua.py
cp "$TMPDIR/organizations.py" /opt/siempria-monitor/backend/routes/organizations.py
rm -rf "$TMPDIR"
sudo systemctl restart siempria-backend
sleep 3
if sudo systemctl is-active --quiet siempria-backend; then
    echo "=== FIX v3 APLICADO - Reiniciar sesion de aray ==="
else
    echo "[!] Error: sudo journalctl -u siempria-backend -n 20"
fi
